window.SHIKAKU_DATA={"index":{"version":"1.0.0","exams":[{"id":"denko2","name":"第二種電気工事士 学科","short":"電工二種","description":"一般用電気工作物等の電気工事に必要な知識（学科試験）","file":"data/denko2.json","count":80},{"id":"otsu4","name":"危険物取扱者 乙種第4類","short":"乙4","description":"引火性液体（ガソリン・灯油・軽油・アルコール類など）の取扱い","file":"data/otsu4.json","count":72},{"id":"tsushin2","name":"2級電気通信工事施工管理 第一次検定","short":"2級電通施工","description":"電気通信工学・電気通信設備・施工管理法・法規","file":"data/tsushin2.json","count":78}]},"exams":{"denko2":{"id":"denko2","name":"第二種電気工事士 学科","short":"電工二種","description":"一般用電気工作物等の電気工事に必要な知識（学科試験）","categories":[{"id":"riron","name":"電気に関する基礎理論","refs":["電気の基礎理論（オームの法則・交流回路・三相回路）"]},{"id":"haiden","name":"配電理論・配線設計","refs":["電気設備の技術基準の解釈 第148条・第149条、内線規程（許容電流）"]},{"id":"kiki","name":"電気機器・材料・工具","refs":["電気機器・工具の一般的な用途（電気技術者試験センター例題範囲）"]},{"id":"seko","name":"電気工事の施工方法","refs":["電気設備の技術基準の解釈（接地 第17・29条、配線工事 第158・159・164条 ほか）"]},{"id":"kensa","name":"検査方法","refs":["電気設備に関する技術基準を定める省令 第58条、解釈 第14条"]},{"id":"zukigo","name":"配線図・図記号","refs":["JIS C 0303:2000 構内電気設備用図記号"]},{"id":"hourei","name":"保安に関する法令","refs":["電気工事士法・同施行令（e-Gov）、電気用品安全法、電気事業法施行規則（小規模発電設備）"]}],"exam":{"questions":50,"minutes":120,"pass":{"type":"total","ratio":0.6,"label":"合格基準点60点（50問・1問2点換算で30問以上正解）"},"note":"本試験は四肢択一50問（一般問題30問程度・配線図問題20問程度）・120分。受験案内に「学科試験における合格基準点は、60点とする」と記載（配点は非公表のため1問2点で換算）。本アプリの模擬試験は全分野から50問（配線図は文章問題で代用）。","source":"https://www.shiken.or.jp/construction/second/department/ , https://www.shiken.or.jp/construction/upload/r8kmousikomiannai1.pdf","checked":"2026-11-05"},"version":"1.0.0","questions":[{"id":"denko2-001","cat":"riron","q":"抵抗10Ωと15Ωを直列に接続し、100Vの直流電圧を加えた。回路に流れる電流[A]は。","choices":["10","16.7","6.7","4"],"answer":3,"exp":"直列の合成抵抗は 10＋15＝25Ω。I＝V/R＝100/25＝4A。"},{"id":"denko2-002","cat":"riron","q":"6Ωと3Ωの抵抗を並列に接続したときの合成抵抗[Ω]は。","choices":["2","9","18","4.5"],"answer":0,"exp":"並列の合成抵抗は（積）/（和）＝(6×3)/(6+3)＝18/9＝2Ω。並列にすると小さい方の抵抗よりさらに小さくなる。"},{"id":"denko2-003","cat":"riron","q":"消費電力1kWの電熱器を2時間使用したときの発熱量[kJ]は。","choices":["7200","3600","2000","120"],"answer":0,"exp":"電力量は 1kW×2h＝2kWh。1kWh＝3600kJ なので 2×3600＝7200kJ。"},{"id":"denko2-004","cat":"riron","q":"直径D・長さLの銅線の抵抗がRである。同じ材質で直径2D・長さ2Lの銅線の抵抗は。","choices":["R/2","R","2R","R/4"],"answer":0,"exp":"抵抗は長さに比例し断面積に反比例する。直径2倍で断面積は4倍、長さ2倍なので R×2/4＝R/2。"},{"id":"denko2-005","cat":"riron","q":"抵抗8Ωと誘導性リアクタンス6Ωを直列に接続し、交流100Vを加えた。回路に流れる電流[A]は。","choices":["12.5","16.7","10","7.1"],"answer":2,"exp":"インピーダンス Z＝√(8²＋6²)＝10Ω。I＝100/10＝10A。抵抗とリアクタンスを単純に足して14Ωとしないこと。"},{"id":"denko2-006","cat":"riron","q":"抵抗8Ωと誘導性リアクタンス6Ωの直列回路に交流100Vを加えたとき、回路の消費電力[W]は。","choices":["1400","600","800","1000"],"answer":2,"exp":"電流は 100/√(8²+6²)＝10A。電力を消費するのは抵抗だけなので P＝I²R＝10²×8＝800W。"},{"id":"denko2-007","cat":"riron","q":"単相交流回路で、電圧100V、電流10A、消費電力800Wのとき、この回路の力率[%]は。","choices":["80","70","125","60"],"answer":0,"exp":"皮相電力は VI＝100×10＝1000VA。力率＝有効電力/皮相電力＝800/1000＝0.8（80%）。"},{"id":"denko2-008","cat":"riron","q":"コイルに加える交流電圧の周波数を50Hzから60Hzに変えた。コイルの誘導性リアクタンスはどうなるか（電圧の大きさは一定）。","choices":["変わらない","1.2倍になる","約0.83倍になる","1.44倍になる"],"answer":1,"exp":"誘導性リアクタンス XL＝2πfL は周波数に比例する。60/50＝1.2倍。なお静電容量のリアクタンス 1/(2πfC) は周波数に反比例する。"},{"id":"denko2-009","cat":"riron","q":"線間電圧200Vの三相交流電源に、1相あたり10Ωの抵抗を△（デルタ）結線で接続した。線電流[A]は。","choices":["60","約11.5","約34.6","20"],"answer":2,"exp":"△結線では相電圧＝線間電圧＝200V。相電流＝200/10＝20A。線電流は相電流の√3倍で 20×1.732≒34.6A。"},{"id":"denko2-010","cat":"riron","q":"線間電圧200Vの三相交流電源に、1相あたり20Ωの抵抗をY（スター）結線で接続した。線電流[A]は。","choices":["約5.8","10","約3.3","約17.3"],"answer":0,"exp":"Y結線の相電圧は 200/√3≒115.5V。線電流＝相電流＝115.5/20≒5.8A。"},{"id":"denko2-011","cat":"riron","q":"定格100V・500Wの電熱器を90Vで使用したときの消費電力[W]は（抵抗値は一定とする）。","choices":["500","405","450","555"],"answer":1,"exp":"P＝V²/R より電力は電圧の2乗に比例する。500×(90/100)²＝500×0.81＝405W。"},{"id":"denko2-012","cat":"haiden","q":"単相3線式100/200V回路で、両側の100V負荷が等しい（平衡している）とき、中性線に流れる電流は。","choices":["片側の負荷電流と同じ","片側の負荷電流の2倍","片側の負荷電流の√3倍","0A"],"answer":3,"exp":"平衡負荷では中性線を流れる電流は互いに打ち消し合って0Aになる。このため中性線の電圧降下も0になる。"},{"id":"denko2-013","cat":"haiden","q":"単相2線式回路で、電線1線あたりの抵抗が0.1Ω、負荷電流が10Aのとき、電線路の電圧降下[V]は。","choices":["4","20","1","2"],"answer":3,"exp":"単相2線式は往復2本分なので 電圧降下＝2Ir＝2×10×0.1＝2V。"},{"id":"denko2-014","cat":"haiden","q":"単相3線式100/200V回路で、電源の各相電圧が105V、各線の抵抗が0.1Ω、平衡負荷で外側の線に20Aが流れている。負荷側の100V端子間電圧[V]は。","choices":["105","104","103","101"],"answer":2,"exp":"平衡負荷なので中性線電流は0。電圧降下は外側の線1本分だけで 20×0.1＝2V。105−2＝103V。"},{"id":"denko2-015","cat":"haiden","q":"三相3線式回路で、電線1線あたりの抵抗が0.2Ω、線電流が10Aのとき、線間の電圧降下[V]はおよそいくらか（負荷は抵抗負荷）。","choices":["6.0","2.0","3.5","4.0"],"answer":2,"exp":"三相3線式の電圧降下は √3Ir＝1.732×10×0.2≒3.46≒3.5V。"},{"id":"denko2-016","cat":"haiden","q":"単相2線式回路で、電線1線あたりの抵抗が0.1Ω、負荷電流が20Aのとき、電線路で失われる電力（電力損失）[W]は。","choices":["40","400","160","80"],"answer":3,"exp":"電力損失は電線2本分で 2I²r＝2×20²×0.1＝80W。"},{"id":"denko2-017","cat":"haiden","q":"600Vビニル絶縁電線（IV）直径1.6mmの許容電流（周囲温度30℃以下）として、一般に用いられる値[A]は。","choices":["48","35","27","19"],"answer":2,"exp":"IV線の許容電流の目安は 1.6mm：27A、2.0mm：35A、2.6mm：48A。"},{"id":"denko2-018","cat":"haiden","q":"金属管にIV直径1.6mmを3本収めて施設した。電流減少係数を0.70とすると、電線1本あたりの許容電流[A]は（小数点以下を7捨8入）。","choices":["19","27","15","22"],"answer":0,"exp":"27A×0.70＝18.9A。7捨8入で19A。同一管内3本以下の電流減少係数は0.70。"},{"id":"denko2-019","cat":"haiden","q":"定格電流20Aの配線用遮断器で保護される分岐回路に使用できる電線（銅線）の最小の太さは。","choices":["直径1.6mm","断面積5.5mm²","直径2.0mm","直径2.6mm"],"answer":0,"exp":"20A配線用遮断器の分岐回路は直径1.6mm以上（コンセントは20A以下）。20Aヒューズの場合は2.0mm以上となる点と混同しない。"},{"id":"denko2-020","cat":"haiden","q":"定格電流30Aの配線用遮断器で保護される分岐回路に施設できるコンセントは。","choices":["定格電流20A以上30A以下のもの","定格電流15Aのもののみ","定格電流30A以上のもののみ","定格電流15A以上20A以下のもの"],"answer":0,"exp":"30A分岐回路は電線2.6mm（5.5mm²）以上、コンセントは20A以上30A以下。"},{"id":"denko2-021","cat":"haiden","q":"定格電流100Aの過電流遮断器で保護された幹線から分岐し、分岐点から6mの位置に分岐回路の過電流遮断器を設けた。分岐回路の電線の許容電流の最小値[A]は。","choices":["25","35","100","55"],"answer":1,"exp":"分岐点から3mを超え8m以下に設ける場合、分岐電線の許容電流は幹線の過電流遮断器定格の35%以上が必要。100×0.35＝35A。8mを超える場合は55%以上。"},{"id":"denko2-022","cat":"haiden","q":"幹線に接続される電動機の定格電流の合計が40A、他の負荷の定格電流の合計が20Aのとき、幹線の許容電流の最小値[A]は（需要率・力率は考えない）。","choices":["64","70","75","60"],"answer":1,"exp":"電動機電流IM＞他の負荷IH かつ IM≦50A なので 1.25IM＋IH＝1.25×40＋20＝70A。"},{"id":"denko2-023","cat":"haiden","q":"低圧架空引込線の取付点の地表上の高さは、原則として何m以上とされているか。","choices":["5m","2.5m","3m","4m"],"answer":3,"exp":"取付点は原則4m以上。技術上やむを得ない場合で交通に支障がないときは2.5m以上とすることができる。"},{"id":"denko2-024","cat":"kiki","q":"三相誘導電動機の回転方向を逆にする方法として正しいものは。","choices":["3本の配線すべてを順に入れ替える","コンデンサを直列に接続する","電源の3本の配線のうち、いずれか2本を入れ替える","電源の周波数を変える"],"answer":2,"exp":"三相のうち任意の2線を入れ替えると回転磁界の向きが逆になり、回転方向が逆転する。3本を順送りに入れ替えても相順は変わらない。"},{"id":"denko2-025","cat":"kiki","q":"周波数50Hz、4極の三相誘導電動機の同期速度[min⁻¹]は。","choices":["3000","1800","1500","1000"],"answer":2,"exp":"同期速度 Ns＝120f/p＝120×50/4＝1500 min⁻¹。実際の回転速度は滑りがあるのでこれより少し遅い。"},{"id":"denko2-026","cat":"kiki","q":"周波数60Hz、6極の三相誘導電動機の同期速度[min⁻¹]は。","choices":["1000","1200","3600","1800"],"answer":1,"exp":"Ns＝120f/p＝120×60/6＝1200 min⁻¹。"},{"id":"denko2-027","cat":"kiki","q":"三相誘導電動機のスターデルタ（Y-△）始動法の目的として正しいものは。","choices":["力率を100%にする","始動トルクを大きくする","回転速度を上げる","始動電流を小さくする"],"answer":3,"exp":"始動時にY結線にすると巻線にかかる電圧が1/√3となり、始動電流は全電圧始動の約1/3になる（始動トルクも約1/3に減る）。"},{"id":"denko2-028","cat":"kiki","q":"低圧進相コンデンサを電動機と並列に接続する主な目的は。","choices":["漏電を防止する","回路の力率を改善する","始動電流を小さくする","回転速度を一定にする"],"answer":1,"exp":"誘導性負荷の遅れ電流をコンデンサの進み電流で打ち消し、力率を改善して線路電流や電力損失を減らす。"},{"id":"denko2-029","cat":"kiki","q":"高周波点灯専用形（Hf）蛍光灯の特徴として誤っているものは。","choices":["点灯に点灯管（グロースタータ）を必要としない","電源電圧が多少変動しても光束の変化が少ない","ちらつきが大きくなる","発光効率が高い"],"answer":2,"exp":"Hf蛍光灯はインバータで高周波点灯するため、ちらつきが少なく効率が高い。"},{"id":"denko2-030","cat":"kiki","q":"リングスリーブ（E形）を圧着するのに使用する工具は。","choices":["リングスリーブ用圧着工具（柄が黄色）","裸圧着端子用圧着工具（柄が赤色）","プライヤ","ワイヤストリッパ"],"answer":0,"exp":"リングスリーブ用は柄が黄色。赤色の柄は裸圧着端子・裸圧着スリーブ用なので使い分ける。"},{"id":"denko2-031","cat":"kiki","q":"金属管を切断した後、管の内面のばり（かえり）を取るのに使用する工具は。","choices":["クリックボール","ディスクグラインダ","リーマ","ノックアウトパンチャ"],"answer":2,"exp":"リーマをクリックボールなどに取り付けて管端内面を面取りし、電線の被覆が傷つかないようにする。"},{"id":"denko2-032","cat":"kiki","q":"金属製のボックスやキャビネットに電線管を接続するための穴をあける工具は。","choices":["ノックアウトパンチャ","合成樹脂管用カッタ","パイプベンダ","リード型ねじ切り器"],"answer":0,"exp":"ノックアウトパンチャは鋼板に丸穴をあける油圧式などの工具。パイプベンダは金属管を曲げる工具。"},{"id":"denko2-033","cat":"kiki","q":"硬質ポリ塩化ビニル電線管（VE管）を曲げ加工する際に使用するものは。","choices":["ガス切断器","パイプベンダ","パイプバイス","トーチランプ"],"answer":3,"exp":"VE管はトーチランプ（ガストーチ）で加熱して柔らかくしてから曲げる。金属管の曲げはパイプベンダ。"},{"id":"denko2-034","cat":"kiki","q":"管の中に電線を通すとき、先に管内に通して電線を引き入れるために使用するものは。","choices":["呼び線挿入器","張線器","ケーブルカッタ","ペンチ"],"answer":0,"exp":"呼び線挿入器（通線器）を管に通し、先端に電線を結んで引き込む。張線器は架空線のたるみを取る工具。"},{"id":"denko2-035","cat":"kiki","q":"「VVF」の名称として正しいものは。","choices":["600V架橋ポリエチレン絶縁ビニルシースケーブル","ビニル絶縁ビニルキャブタイヤケーブル","600Vビニル絶縁ビニルシースケーブル平形","600Vビニル絶縁電線"],"answer":2,"exp":"VVFは住宅の屋内配線で最もよく使われる平形ケーブル。丸形はVVR、IVはビニル絶縁電線、CVは架橋ポリエチレン絶縁ケーブル。"},{"id":"denko2-036","cat":"kiki","q":"「EM-EEF」と表記される電線の特徴として正しいものは。","choices":["絶縁体・シースにポリエチレンを使った耐燃性のエコケーブル","ビニル絶縁のキャブタイヤケーブル","屋外用ビニル絶縁電線","引込用ビニル絶縁電線"],"answer":0,"exp":"EM（エコマテリアル）は燃やしても有害なハロゲンガスが出にくい環境配慮型ケーブル。"},{"id":"denko2-037","cat":"kiki","q":"漏電遮断器の主な役割として正しいものは。","choices":["雷サージを吸収する","地絡（漏電）を検出して自動的に回路を遮断する","電圧を一定に保つ","力率を改善する"],"answer":1,"exp":"漏電遮断器は零相変流器で漏れ電流を検出して回路を遮断し、感電や漏電火災を防ぐ。"},{"id":"denko2-038","cat":"seko","q":"D種接地工事の接地抵抗値は原則何Ω以下か（0.5秒以内に動作する漏電遮断器を施設していない場合）。","choices":["1000Ω以下","10Ω以下","500Ω以下","100Ω以下"],"answer":3,"exp":"D種は100Ω以下。地絡時に0.5秒以内に自動遮断する装置を施設すれば500Ω以下でよい。"},{"id":"denko2-039","cat":"seko","q":"使用電圧が300Vを超える低圧の機械器具の金属製外箱に施す接地工事は。","choices":["C種接地工事","B種接地工事","A種接地工事","D種接地工事"],"answer":0,"exp":"300V以下の低圧はD種、300V超の低圧はC種（10Ω以下、0.5秒以内の遮断装置があれば500Ω以下）。"},{"id":"denko2-040","cat":"seko","q":"D種接地工事の接地線（軟銅線）の太さは、原則として直径何mm以上か。","choices":["1.6mm","1.2mm","2.0mm","2.6mm"],"answer":0,"exp":"C種・D種接地工事の接地線は直径1.6mm以上の軟銅線（移動電線の場合などは別規定）。"},{"id":"denko2-041","cat":"seko","q":"D種接地工事を省略できないものは。","choices":["二重絶縁構造の電動工具","乾燥した場所に施設した対地電圧100Vの機器の金属製外箱","水気のある場所に施設した三相200V電動機の鉄台（漏電遮断器なし）","乾燥した木製の床の上で取り扱う低圧用機器"],"answer":2,"exp":"対地電圧150V以下で乾燥した場所、二重絶縁構造、絶縁性の床の上で取り扱う場合などは省略できる。水気のある場所は省略できない。"},{"id":"denko2-042","cat":"seko","q":"VVFケーブルを造営材の側面に沿って取り付ける場合、支持点間の距離は何m以下とするか。","choices":["1m","2m","1.5m","3m"],"answer":1,"exp":"ケーブルを造営材の下面・側面に沿わせる場合の支持点間距離は2m以下（キャブタイヤケーブルは1m以下）。"},{"id":"denko2-043","cat":"seko","q":"コンクリートに埋め込む金属管の管の厚さは何mm以上でなければならないか。","choices":["0.8mm","1.2mm","1.0mm","2.0mm"],"answer":1,"exp":"コンクリートに埋設する金属管は厚さ1.2mm以上（それ以外は1mm以上が原則）。"},{"id":"denko2-044","cat":"seko","q":"金属管工事の施工方法として誤っているものは。","choices":["電線に600Vビニル絶縁電線を使用した","管とボックスの接続にロックナットを使用した","低圧屋内配線の使用電圧が200Vなので管にD種接地工事を施した","管内で電線を接続し、絶縁テープで十分に巻いた"],"answer":3,"exp":"金属管・合成樹脂管工事では管内で電線の接続点を設けてはならない。接続はボックス内で行う。"},{"id":"denko2-045","cat":"seko","q":"合成樹脂管工事で、管を造営材に取り付ける際の支持点間の距離は何m以下か。","choices":["3m","1.5m","1m","2m"],"answer":1,"exp":"合成樹脂管の支持点間距離は1.5m以下。管端・接続点の近く（0.3m程度）にも支持点を設ける。"},{"id":"denko2-046","cat":"seko","q":"合成樹脂管相互を接着剤を使用せずに差込み接続する場合、管の差込み深さは管の外径の何倍以上か。","choices":["2.0倍","0.5倍","0.8倍","1.2倍"],"answer":3,"exp":"差込み深さは外径の1.2倍以上。接着剤を使用する場合は0.8倍以上でよい。"},{"id":"denko2-047","cat":"seko","q":"電線相互を接続する場合の一般的な条件として誤っているものは。","choices":["電気抵抗を増加させない","接続管などの器具を使用するか、ろう付けする","電線の引張り強さを30%減少させてもよい","接続部分を絶縁電線と同等以上に絶縁する"],"answer":2,"exp":"電線の引張り強さを20%以上減少させてはならない（80%以上を保持）。"},{"id":"denko2-048","cat":"seko","q":"直径1.6mmのVVFの心線3本をE形リングスリーブで終端接続する。使用するスリーブと刻印の組合せとして正しいものは。","choices":["大スリーブ・刻印「大」","小スリーブ・刻印「○」","小スリーブ・刻印「小」","中スリーブ・刻印「中」"],"answer":2,"exp":"1.6mm×2本は小スリーブ「○」、1.6mm×3〜4本は小スリーブ「小」、1.6mm×5〜6本は中スリーブ「中」。"},{"id":"denko2-049","cat":"seko","q":"点検できない隠ぺい場所（乾燥した場所）で施工できない低圧屋内配線工事は。","choices":["金属管工事","合成樹脂管工事（CD管を除く）","がいし引き工事","ケーブル工事"],"answer":2,"exp":"がいし引き工事は展開した場所と点検できる隠ぺい場所に限られる。金属管・合成樹脂管・ケーブル工事はどの場所でも施工できる（条件あり）。"},{"id":"denko2-050","cat":"seko","q":"地中電線路を直接埋設式で施設する場合、車両その他の重量物の圧力を受けるおそれがある場所の土冠り（埋設深さ）は何m以上か。","choices":["0.3m","0.6m","1.2m","1.0m"],"answer":2,"exp":"重量物の圧力を受けるおそれがある場所は1.2m以上、その他の場所は0.6m以上。"},{"id":"denko2-051","cat":"seko","q":"ライティングダクト工事の施工方法として誤っているものは。","choices":["造営材を貫通しないように施設した","ダクトの開口部を上向きに取り付けた","ダクトの支持点間の距離を2mとした","ダクトの終端部を閉そくした"],"answer":1,"exp":"ライティングダクトは開口部を下向きに施設するのが原則（ほこりや異物が入らないように）。支持点間は2m以下。"},{"id":"denko2-052","cat":"kensa","q":"単相100V（対地電圧100V）の低圧電路の電線相互間および電路と大地間の絶縁抵抗の最小値は。","choices":["0.1MΩ","0.2MΩ","0.4MΩ","1MΩ"],"answer":0,"exp":"使用電圧300V以下で対地電圧150V以下は0.1MΩ以上。対地電圧150V超（三相200Vなど）は0.2MΩ以上、300V超は0.4MΩ以上。"},{"id":"denko2-053","cat":"kensa","q":"三相200V（対地電圧200V）の電動機回路の絶縁抵抗の最小値は。","choices":["0.2MΩ","0.4MΩ","0.1MΩ","1MΩ"],"answer":0,"exp":"300V以下で対地電圧150Vを超えるので0.2MΩ以上。"},{"id":"denko2-054","cat":"kensa","q":"絶縁抵抗の測定が困難な場合、使用電圧が加わった状態での漏えい電流を何mA以下に保てばよいとされているか。","choices":["1mA","0.1mA","5mA","30mA"],"answer":0,"exp":"測定が困難な場合は漏えい電流を1mA以下に保つこととされている。"},{"id":"denko2-055","cat":"kensa","q":"絶縁抵抗の測定に使用する測定器は。","choices":["検相器","照度計","接地抵抗計","絶縁抵抗計"],"answer":3,"exp":"絶縁抵抗計（メガー）で電路と大地間、電線相互間の絶縁抵抗を測る。接地抵抗計は接地極の抵抗を測る。"},{"id":"denko2-056","cat":"kensa","q":"一般住宅の屋内配線の竣工検査で、通常は行わないものは。","choices":["屋内配線の導体抵抗の測定","接地抵抗の測定","絶縁抵抗の測定","目視による点検"],"answer":0,"exp":"竣工検査では目視点検・絶縁抵抗測定・接地抵抗測定・導通試験などを行う。導体抵抗の測定は通常行わない。"},{"id":"denko2-057","cat":"kensa","q":"接地抵抗計（電池式）で接地抵抗を測定する場合の補助接地極の配置として適切なものは。","choices":["被測定接地極を中心に三角形に配置する","補助接地極は使用しない","被測定接地極からほぼ一直線上に約10m間隔で2本配置する","被測定接地極のすぐ隣に1本だけ配置する"],"answer":2,"exp":"被測定接地極E、補助接地極P、Cをほぼ一直線に約10m間隔で配置する。"},{"id":"denko2-058","cat":"kensa","q":"クランプ形漏れ電流計で単相2線式回路の漏れ電流を測定する方法として正しいものは。","choices":["接地線と電線1本を一括してクランプする","2本の電線を一括してクランプする","1本の電線だけをクランプする","電源を切ってからクランプする"],"answer":1,"exp":"往復の電流は打ち消し合うので、2本（三相なら3本）一括でクランプすると差分の漏れ電流だけが測れる。"},{"id":"denko2-059","cat":"kensa","q":"三相回路の相順（相回転）を確認するのに使用する測定器は。","choices":["検電器","周波数計","検相器","回路計"],"answer":2,"exp":"検相器で相順を確認する。逆相だと電動機が逆回転する。検電器は充電の有無を調べる。"},{"id":"denko2-060","cat":"zukigo","q":"屋内配線図で、コンセントの図記号に傍記「EET」とあるものは。","choices":["接地極付コンセント","防雨形コンセント","接地極付接地端子付コンセント","接地端子付コンセント"],"answer":2,"exp":"E＝接地極付、ET＝接地端子付、EET＝接地極付接地端子付。電子レンジや洗濯機用によく使う。"},{"id":"denko2-061","cat":"zukigo","q":"コンセントの図記号の傍記「WP」が表すものは。","choices":["防雨形","引掛形","医用","抜け止め形"],"answer":0,"exp":"WP＝防雨形、LK＝抜け止め形、T＝引掛形、H＝医用。"},{"id":"denko2-062","cat":"zukigo","q":"点滅器（スイッチ）の図記号に傍記「3」とあるものは。","choices":["3連用スイッチ","3路スイッチ","3極スイッチ","定格3Aのスイッチ"],"answer":1,"exp":"傍記の数字3は3路、4は4路。2極は「2P」と傍記する。"},{"id":"denko2-063","cat":"zukigo","q":"点滅器の図記号に傍記「L」とあるものは。","choices":["遅延スイッチ","確認表示灯（パイロットランプ）内蔵スイッチ","位置表示灯内蔵スイッチ","自動点滅器"],"answer":1,"exp":"L＝確認表示灯内蔵（ONで点灯）、H＝位置表示灯内蔵（OFFで点灯）、A＝自動点滅器、D＝遅延スイッチ。"},{"id":"denko2-064","cat":"zukigo","q":"屋内配線図で「天井隠ぺい配線」を表す線の種類は。","choices":["実線","点線","一点鎖線","破線"],"answer":0,"exp":"天井隠ぺい配線＝実線、床隠ぺい配線＝破線、露出配線＝点線。"},{"id":"denko2-065","cat":"zukigo","q":"配線図の電線管の記号「(PF16)」が表すものは。","choices":["ねじなし電線管","2種金属製可とう電線管","合成樹脂製可とう電線管","硬質ポリ塩化ビニル電線管"],"answer":2,"exp":"PF＝合成樹脂製可とう電線管、VE＝硬質ポリ塩化ビニル電線管、E＝ねじなし電線管、F2＝2種金属製可とう電線管。"},{"id":"denko2-066","cat":"zukigo","q":"照明器具の図記号に傍記「DL」とあるものは。","choices":["シーリング（天井直付）","ダウンライト","シャンデリヤ","ペンダント"],"answer":1,"exp":"DL＝ダウンライト、CL＝シーリング、CH＝シャンデリヤ。"},{"id":"denko2-067","cat":"zukigo","q":"1つの照明器具を2か所の3路スイッチで点滅する回路で、2個の3路スイッチの端子1と端子3どうしを結ぶ渡り線は何本か。","choices":["2本","1本","4本","3本"],"answer":0,"exp":"3路スイッチは端子0（共通）と端子1・3を切り替える。2個の3路スイッチの1どうし・3どうしを2本の渡り線で結び、一方の0に電源の非接地側、もう一方の0に照明器具を接続する。"},{"id":"denko2-068","cat":"hourei","q":"電気工事士法で、電気工事士免状がなくても従事できる作業（軽微な工事）は。","choices":["電力量計を取り付ける作業","電線管に電線を収める作業","接地線を接地極に接続する作業","埋込形コンセントを取り替える作業"],"answer":0,"exp":"電力量計・電流制限器・ヒューズの取付け、取外しは軽微な工事で免状不要。埋込形コンセントの取替えや接地工事は電気工事士でなければできない。"},{"id":"denko2-069","cat":"hourei","q":"第二種電気工事士免状を交付するのは。","choices":["電気技術者試験センター理事長","経済産業大臣","都道府県知事","市町村長"],"answer":2,"exp":"電気工事士免状（第一種・第二種）は都道府県知事が交付する。"},{"id":"denko2-070","cat":"hourei","q":"電気工事士が結婚して氏名が変わった。必要な手続きは。","choices":["免状を返納して再受験する","手続きは不要","住所地を管轄する経済産業局長に届け出る","免状を交付した都道府県知事に書換えを申請する"],"answer":3,"exp":"氏名変更は免状を交付した都道府県知事に書換え申請。住所は免状の記載事項ではないので書換え不要。"},{"id":"denko2-071","cat":"hourei","q":"電気用品安全法で、特定電気用品に表示が義務づけられている記号は。","choices":["JISマーク","丸形のPSEマーク（(PS)E）","ひし形のPSEマーク（<PS>E）","Sマーク"],"answer":2,"exp":"特定電気用品はひし形、特定電気用品以外の電気用品は丸形のPSEマーク。"},{"id":"denko2-072","cat":"hourei","q":"電気設備に関する技術基準を定める省令で、低圧とされる電圧の範囲は。","choices":["直流750V以下、交流600V以下","直流600V以下、交流750V以下","直流・交流とも600V以下","直流・交流とも7000V以下"],"answer":0,"exp":"低圧：直流750V以下・交流600V以下。高圧：それを超え7000V以下。特別高圧：7000V超。"},{"id":"denko2-073","cat":"hourei","q":"一般用電気工作物となる小出力発電設備の太陽電池発電設備の出力の条件は（低圧で同一構内に他の発電設備がない場合）。","choices":["100kW未満","50kW未満","20kW未満","10kW未満"],"answer":3,"exp":"2023年3月施行の改正以降、太陽電池発電設備で小出力発電設備に当たるのは10kW未満（10kW以上50kW未満は小規模事業用電気工作物）。"},{"id":"denko2-074","cat":"hourei","q":"電気工事業の業務の適正化に関する法律で、一般用電気工事のみを行う営業所に備えなければならない器具の組合せは。","choices":["絶縁抵抗計・接地抵抗計・抵抗と交流電圧を測定できる回路計","接地抵抗計・クランプ形電流計・騒音計","絶縁抵抗計・検相器・照度計","回路計・周波数計・低圧検電器"],"answer":0,"exp":"一般用電気工事の営業所は絶縁抵抗計、接地抵抗計、抵抗及び交流電圧を測定できる回路計を備える。"},{"id":"denko2-075","cat":"hourei","q":"電気工事士が電気工事の作業に従事するときの義務として正しいものは。","choices":["作業前に経済産業大臣の許可を受ける","電気工事士免状を携帯する","免状の写しを現場に掲示する","作業のたびに都道府県知事に届け出る"],"answer":1,"exp":"電気工事士は作業に従事するとき免状を携帯しなければならない。"},{"id":"denko2-076","cat":"haiden","q":"金属管にIV直径1.6mmを4本収めて施設した。電流減少係数を0.63とすると、電線1本あたりの許容電流[A]は（小数点以下7捨8入）。","choices":["27","17","19","15"],"answer":1,"exp":"27A×0.63＝17.01A → 17A。電流減少係数は3本以下0.70、4本0.63、5〜6本0.56。"},{"id":"denko2-077","cat":"seko","q":"直径2.0mmの電線2本をE形リングスリーブで終端接続する。スリーブと刻印の組合せとして正しいものは。","choices":["小スリーブ・刻印「○」","中スリーブ・刻印「中」","小スリーブ・刻印「小」","中スリーブ・刻印「小」"],"answer":2,"exp":"刻印「○」は1.6mm×2本のときだけ。2.0mm×2本は小スリーブで刻印「小」、2.0mm×3〜4本は中スリーブで刻印「中」。"},{"id":"denko2-078","cat":"kensa","q":"使用電圧400V（300Vを超える低圧）の電路の絶縁抵抗の最小値は。","choices":["1MΩ","0.1MΩ","0.4MΩ","0.2MΩ"],"answer":2,"exp":"電技省令第58条：300V以下で対地電圧150V以下は0.1MΩ、300V以下のその他は0.2MΩ、300V超は0.4MΩ以上。"},{"id":"denko2-079","cat":"hourei","q":"電気工事士法で、電気工事士でなくても行える「軽微な工事」に該当するものは。","choices":["配線器具を造営材に固定する工事","電線管とボックスを接続する工事","インターホンに使う小型変圧器（二次電圧36V以下）の二次側の配線工事","露出型コンセントを取り換える工事"],"answer":2,"exp":"電気工事士法施行令第1条に、二次電圧36V以下の小型変圧器の二次側の配線工事、電力量計・電流制限器・ヒューズの取付け・取外しなどが軽微な工事として定められている。"},{"id":"denko2-080","cat":"hourei","q":"2023年3月20日施行の改正電気事業法で「小規模事業用電気工作物」に区分された太陽電池発電設備の出力は。","choices":["20kW未満","10kW以上50kW未満","50kW以上500kW未満","10kW未満"],"answer":1,"exp":"10kW未満の太陽電池発電設備は一般用電気工作物、10kW以上50kW未満は小規模事業用電気工作物（技術基準適合維持・基礎情報届出などの義務）。"}]},"otsu4":{"id":"otsu4","name":"危険物取扱者 乙種第4類","short":"乙4","description":"引火性液体（ガソリン・灯油・軽油・アルコール類など）の取扱い","categories":[{"id":"hourei","name":"危険物に関する法令","short":"法令","refs":["消防法・危険物の規制に関する政令（別表第三＝指定数量）・危険物の規制に関する規則（e-Gov法令検索）","総務省消防庁・各消防本部の定期点検/保安講習案内"]},{"id":"butsuka","name":"基礎的な物理学・化学","short":"物化","refs":["高校化学・物理の基本事項（燃焼、熱量、酸化還元など）"]},{"id":"seishitsu","name":"性質・火災予防・消火","short":"性消","refs":["乙4テキスト類の物性代表値（引火点・発火点・燃焼範囲等）。製品・資料により数値に幅があります"]}],"exam":{"questions":35,"minutes":120,"distribution":{"hourei":15,"butsuka":10,"seishitsu":10},"pass":{"type":"perCategory","ratio":0.6,"label":"試験科目ごとにそれぞれ60%以上（法令9問・物化6問・性消6問以上）"},"note":"本試験は五肢択一・試験時間2時間（乙種）。本アプリは4択で出題します。合格基準は消防試験研究センター「試験の方法」による。","source":"https://www.shoubo-shiken.or.jp/kikenbutsu/annai/way.html , https://www.shoubo-shiken.or.jp/kikenbutsu/annai/subject.html","checked":"2026-11-05"},"version":"1.0.0","questions":[{"id":"otsu4-001","cat":"hourei","q":"消防法上の危険物の類別と性質の組合せとして誤っているものは。","choices":["第3類 ― 酸化性液体","第4類 ― 引火性液体","第1類 ― 酸化性固体","第2類 ― 可燃性固体"],"answer":0,"exp":"第3類は自然発火性物質及び禁水性物質。酸化性液体は第6類。第5類は自己反応性物質。"},{"id":"otsu4-002","cat":"hourei","q":"灯油の指定数量は。","choices":["400L","200L","2000L","1000L"],"answer":3,"exp":"灯油・軽油は第2石油類（非水溶性）で1000L。ガソリンは第1石油類（非水溶性）で200L。"},{"id":"otsu4-003","cat":"hourei","q":"第4類危険物の品名と指定数量の組合せとして誤っているものは。","choices":["特殊引火物 ― 50L","重油 ― 1000L","アルコール類 ― 400L","動植物油類 ― 10000L"],"answer":1,"exp":"重油は第3石油類（非水溶性）で2000L。第4石油類は6000L。"},{"id":"otsu4-004","cat":"hourei","q":"ガソリン400L、灯油1000L、重油2000Lを同一の場所で貯蔵する。指定数量の倍数の合計は。","choices":["3","4","5","2"],"answer":1,"exp":"ガソリン400/200＝2、灯油1000/1000＝1、重油2000/2000＝1。合計4倍。"},{"id":"otsu4-005","cat":"hourei","q":"ガソリン100L、軽油500L、エタノール200Lを貯蔵する場合の指定数量の倍数の合計は。","choices":["1.5","1.0","2.5","0.8"],"answer":0,"exp":"ガソリン100/200＝0.5、軽油500/1000＝0.5、エタノール（アルコール類）200/400＝0.5。合計1.5倍。"},{"id":"otsu4-006","cat":"hourei","q":"指定数量以上の危険物を製造所等以外の場所で仮に貯蔵・取り扱う場合の手続きとして正しいものは。","choices":["都道府県知事に届け出れば期限なく可能","市町村長の許可を受けて、30日以内に限り可能","所轄消防長または消防署長の承認を受けて、10日以内に限り可能","仮に貯蔵することは一切できない"],"answer":2,"exp":"仮貯蔵・仮取扱いは消防長または消防署長の承認を受け、10日以内に限られる。"},{"id":"otsu4-007","cat":"hourei","q":"指定数量未満の危険物の貯蔵・取扱いの技術上の基準を定めているのは。","choices":["市町村条例","消防法","都道府県規則","危険物の規制に関する政令"],"answer":0,"exp":"指定数量未満の危険物（少量危険物）の基準は市町村の火災予防条例で定められる。"},{"id":"otsu4-008","cat":"hourei","q":"製造所等を設置しようとするとき、許可を受ける相手として正しいものは。","choices":["消防署長","市町村長等","都道府県公安委員会","総務大臣"],"answer":1,"exp":"製造所等の設置・変更は市町村長等（市町村長、都道府県知事、総務大臣のいずれか）の許可が必要。"},{"id":"otsu4-009","cat":"hourei","q":"製造所等の位置・構造・設備を変更しないで、貯蔵する危険物の品名や数量を変更する場合の手続きは。","choices":["変更しようとする日の10日前までに市町村長等に届け出る","変更後遅滞なく市町村長等に届け出る","消防長の承認を受ける","市町村長等の許可を受ける"],"answer":0,"exp":"品名・数量・指定数量の倍数の変更は、変更しようとする日の10日前までに届出。"},{"id":"otsu4-010","cat":"hourei","q":"法令上、市町村長等に「遅滞なく」届け出なければならないものとして誤っているものは。","choices":["製造所等の用途を廃止したとき","危険物施設保安員を定めたとき","製造所等を譲り受けたとき","危険物保安監督者を定めたとき"],"answer":1,"exp":"危険物施設保安員の選任・解任は届出不要。廃止・譲渡引渡し・危険物保安監督者の選任解任・危険物保安統括管理者の選任解任は遅滞なく届出。"},{"id":"otsu4-011","cat":"hourei","q":"製造所等の変更工事中に、変更工事に係る部分以外の部分を使用したい。必要な手続きは。","choices":["消防長の仮貯蔵の承認を受ける","市町村長等の仮使用の承認を受ける","特に手続きは不要","完成検査前検査を受ける"],"answer":1,"exp":"仮使用は変更工事中に工事以外の部分を市町村長等の承認を受けて使用する制度。仮貯蔵と混同しないこと。"},{"id":"otsu4-012","cat":"hourei","q":"丙種危険物取扱者が取り扱うことができる危険物として誤っているものは。","choices":["動植物油類","ガソリン","軽油","ベンゼン"],"answer":3,"exp":"丙種はガソリン、灯油、軽油、第3石油類（重油・潤滑油・引火点130℃以上のもの）、第4石油類、動植物油類のみ。ベンゼンは扱えない。"},{"id":"otsu4-013","cat":"hourei","q":"危険物取扱者以外の者が製造所等で危険物を取り扱うことができる条件として正しいものは。","choices":["指定数量未満であれば立会いなしでよい","甲種または当該危険物を扱える乙種危険物取扱者が立ち会う","危険物施設保安員が立ち会う","丙種危険物取扱者が立ち会う"],"answer":1,"exp":"立会いができるのは甲種と、その類の免状を持つ乙種のみ。丙種は立会いができない。"},{"id":"otsu4-014","cat":"hourei","q":"危険物取扱者免状の書換えが必要な場合として正しいものは。","choices":["免状の写真が撮影から10年を経過したとき","現住所が変わったとき","保安講習を受講したとき","勤務先が変わったとき"],"answer":0,"exp":"書換えが必要なのは氏名・本籍地の属する都道府県の変更、写真が10年経過したとき。現住所は記載事項ではない。"},{"id":"otsu4-015","cat":"hourei","q":"免状を亡失して再交付を受けた後、亡失した免状を発見した。正しい対応は。","choices":["発見した免状を10日以内に再交付を受けた都道府県知事に提出する","発見した免状をそのまま予備として保管する","発見した免状を破棄すればよい","30日以内に市町村長に提出する"],"answer":0,"exp":"亡失免状を発見したら10日以内に再交付を受けた知事に提出する。"},{"id":"otsu4-016","cat":"hourei","q":"製造所等で危険物の取扱作業に従事している危険物取扱者の保安講習の受講時期として正しいものは。","choices":["危険物保安監督者に選任されたときだけ受講する","受講日以後の最初の4月1日から3年以内ごとに受講する","毎年1回受講する","免状交付日から5年ごとに受講する"],"answer":1,"exp":"従事開始日から1年以内（過去2年以内に免状交付・講習受講していればその日以後の最初の4月1日から3年以内）に受け、以後は受講日以後の最初の4月1日から3年以内ごと。"},{"id":"otsu4-017","cat":"hourei","q":"危険物保安監督者に選任できる者として正しいものは。","choices":["危険物取扱者でない保安責任者","製造所等で6か月以上の実務経験がある甲種または乙種危険物取扱者","実務経験1年以上の丙種危険物取扱者","実務経験のない丙種危険物取扱者"],"answer":1,"exp":"危険物保安監督者は甲種または乙種（その類）で、製造所等における実務経験6か月以上が必要。丙種は選任できない。"},{"id":"otsu4-018","cat":"hourei","q":"定期点検を行わなければならない製造所等として、指定数量の倍数にかかわらず対象となるものは。","choices":["屋内タンク貯蔵所","移動タンク貯蔵所","簡易タンク貯蔵所","販売取扱所"],"answer":1,"exp":"地下タンク貯蔵所、移動タンク貯蔵所、地下タンクを有する製造所・給油取扱所・一般取扱所は規模にかかわらず定期点検が必要。屋内タンク・簡易タンク・販売取扱所は対象外。"},{"id":"otsu4-019","cat":"hourei","q":"定期点検の実施回数と記録の保存期間の組合せとして正しいものは（原則）。","choices":["1年に1回以上・3年間保存","2年に1回以上・5年間保存","半年に1回以上・1年間保存","3年に1回以上・10年間保存"],"answer":0,"exp":"定期点検は原則1年に1回以上行い、記録は原則3年間保存する。"},{"id":"otsu4-020","cat":"hourei","q":"製造所と学校・病院との間に確保しなければならない保安距離は。","choices":["10m以上","20m以上","30m以上","50m以上"],"answer":2,"exp":"保安距離：住居10m、高圧ガス施設20m、学校・病院・劇場等30m、重要文化財等50m以上。"},{"id":"otsu4-021","cat":"hourei","q":"移動タンク貯蔵所で危険物を移送する際の規定として誤っているものは。","choices":["乗車する危険物取扱者は免状を携帯する","危険物取扱者は免状の写しを事務所に保管しておけば乗車しなくてよい","移送する危険物を取り扱える危険物取扱者が乗車する","完成検査済証を車両に備え付ける"],"answer":1,"exp":"移送には当該危険物を取り扱える危険物取扱者が乗車し、免状を携帯しなければならない。"},{"id":"otsu4-022","cat":"hourei","q":"第4類危険物を貯蔵する製造所等に掲げる注意事項の掲示板として正しいものは。","choices":["黄地に黒文字で「危」","青地に白文字で「禁水」","白地に黒文字で「火気注意」","赤地に白文字で「火気厳禁」"],"answer":3,"exp":"第4類は「火気厳禁」（赤地に白文字）。「禁水」は青地に白文字で第3類の禁水性物品などに用いる。"},{"id":"otsu4-023","cat":"hourei","q":"消火設備の区分で、小型消火器・乾燥砂・水バケツが該当するのは。","choices":["第4種消火設備","第3種消火設備","第1種消火設備","第5種消火設備"],"answer":3,"exp":"第1種：屋内・屋外消火栓、第2種：スプリンクラー、第3種：泡・粉末等の固定消火設備、第4種：大型消火器、第5種：小型消火器・乾燥砂など。"},{"id":"otsu4-024","cat":"hourei","q":"危険物の所要単位の計算で、1所要単位とされる危険物の量は。","choices":["指定数量の10倍","指定数量の5倍","指定数量の100倍","指定数量の1倍"],"answer":0,"exp":"危険物は指定数量の10倍を1所要単位とする。"},{"id":"otsu4-025","cat":"hourei","q":"給油取扱所での取扱いの基準として誤っているものは。","choices":["固定給油設備を使用して直接給油する","自動車に給油するとき、エンジンは停止しなくてもよい","移動タンク貯蔵所から地下タンクに注入中は、そのタンクにつながる固定給油設備を使用しない","給油空地からはみ出した状態で給油しない"],"answer":1,"exp":"自動車等に給油するときはエンジンを停止させなければならない。"},{"id":"otsu4-026","cat":"butsuka","q":"燃焼の三要素の組合せとして正しいものは。","choices":["可燃物・酸素供給源・点火源","酸素・二酸化炭素・熱","可燃物・酸素・水","可燃物・窒素・点火源"],"answer":0,"exp":"燃焼には可燃物、酸素供給源、点火源（熱源）の三つがそろう必要がある。どれか一つを除けば消火できる。"},{"id":"otsu4-027","cat":"butsuka","q":"引火点の説明として正しいものは。","choices":["液体が沸騰を始める温度","点火源がなくても自ら燃え出す最低の温度","蒸気が燃焼範囲の上限に達する温度","液体の表面に、点火源により燃焼するのに十分な濃度の蒸気を発生する最低の液温"],"answer":3,"exp":"点火源なしで燃え出す最低温度は発火点。引火点は点火源があれば燃える最低の液温。"},{"id":"otsu4-028","cat":"butsuka","q":"ある可燃性液体の燃焼範囲が1.4〜7.6vol%である。燃焼する可能性があるものは（点火源あり）。","choices":["空気中の蒸気濃度が5vol%のとき","空気中の蒸気濃度が0.5vol%のとき","空気中の蒸気濃度が10vol%のとき","空気中の蒸気濃度が20vol%のとき"],"answer":0,"exp":"蒸気濃度が燃焼範囲（下限〜上限）の中にあるときだけ点火源で燃焼する。薄すぎても濃すぎても燃えない。"},{"id":"otsu4-029","cat":"butsuka","q":"第4類危険物（引火性液体）の主な燃焼の形態は。","choices":["蒸発燃焼","分解燃焼","表面燃焼","自己燃焼（内部燃焼）"],"answer":0,"exp":"液体から発生した蒸気が空気と混ざって燃える蒸発燃焼。木炭は表面燃焼、木材は分解燃焼、ニトロセルロースは自己燃焼。"},{"id":"otsu4-030","cat":"butsuka","q":"物質と燃焼の形態の組合せとして誤っているものは。","choices":["石炭 ― 分解燃焼","硫黄 ― 蒸発燃焼","ガソリン ― 蒸発燃焼","木炭 ― 分解燃焼"],"answer":3,"exp":"木炭やコークスは表面燃焼（炎を出さずに表面で燃える）。"},{"id":"otsu4-031","cat":"butsuka","q":"窒息消火で燃焼が停止するとされる空気中の酸素濃度はおおむね何vol%以下か。","choices":["約14〜15vol%","約21vol%","約18vol%","約5vol%"],"answer":0,"exp":"一般に酸素濃度をおおむね14〜15vol%以下にすると燃焼は継続しない（空気中の酸素は約21vol%）。"},{"id":"otsu4-032","cat":"butsuka","q":"消火方法とその主な原理の組合せとして誤っているものは。","choices":["ガスの元栓を閉める ― 除去消火","泡で燃焼面を覆う ― 窒息消火","ハロゲン化物消火剤で燃焼の連鎖反応を抑える ― 抑制（負触媒）消火","水をかけて消す ― 除去消火"],"answer":3,"exp":"水は蒸発熱が大きく主に冷却消火。可燃物を取り除くのが除去消火。"},{"id":"otsu4-033","cat":"butsuka","q":"静電気に関する記述として誤っているものは。","choices":["電気の不良導体ほど帯電しやすい","液体の流速が大きいほど発生しやすい","湿度が高いほど静電気は蓄積しやすい","接地は静電気の蓄積防止に有効である"],"answer":2,"exp":"湿度が低い（乾燥している）ほど静電気は蓄積しやすい。対策は接地、加湿、流速を遅くすることなど。"},{"id":"otsu4-034","cat":"butsuka","q":"20℃の水100gを50℃にするのに必要な熱量はおよそいくらか（水の比熱を4.2J/(g・K)とする）。","choices":["4.2kJ","21.0kJ","12.6kJ","8.4kJ"],"answer":2,"exp":"熱量 Q＝比熱×質量×温度差＝4.2×100×(50−20)＝12600J＝12.6kJ。"},{"id":"otsu4-035","cat":"butsuka","q":"ガソリン1000Lを10℃から30℃に温めたとき、体積の増加量はおよそいくらか（体膨張率1.35×10⁻³ K⁻¹）。","choices":["13.5L","2.7L","135L","27L"],"answer":3,"exp":"増加量＝元の体積×体膨張率×温度差＝1000×0.00135×20＝27L。容器に空間容積を確保する理由。"},{"id":"otsu4-036","cat":"butsuka","q":"熱の移動の仕方のうち、太陽の熱が地球に届くような移動を何というか。","choices":["対流","放射（ふく射）","蒸発","伝導"],"answer":1,"exp":"熱の移動は伝導・対流・放射の3種類。空間を電磁波として伝わるのが放射。"},{"id":"otsu4-037","cat":"butsuka","q":"沸点に関する記述として正しいものは。","choices":["外圧が低くなると沸点は低くなる","不揮発性物質が溶けると沸点は低くなる","外圧が低くなると沸点は高くなる","沸点は外圧に関係なく一定である"],"answer":0,"exp":"液体の蒸気圧が外圧と等しくなる温度が沸点。高山で水が100℃未満で沸騰するのはこのため。溶質が溶けると沸点上昇が起こる。"},{"id":"otsu4-038","cat":"butsuka","q":"酸化の説明として誤っているものは。","choices":["物質が酸素と結びつく","物質が水素と結びつく","物質が水素を失う","物質が電子を失う"],"answer":1,"exp":"水素と結びつくのは還元。酸化は酸素と化合する・水素を失う・電子を失う反応。"},{"id":"otsu4-039","cat":"butsuka","q":"物理変化に該当するものは。","choices":["水を電気分解して水素と酸素が発生する","鉄がさびる","木材が燃える","氷が溶けて水になる"],"answer":3,"exp":"状態が変わるだけで別の物質にならないのが物理変化。さび・燃焼・電気分解は化学変化。"},{"id":"otsu4-040","cat":"butsuka","q":"物質の分類として正しいものは。","choices":["酸素は化合物である","水は単体である","ガソリンは混合物である","空気は化合物である"],"answer":2,"exp":"ガソリンはさまざまな炭化水素の混合物。水は化合物、酸素は単体、空気は混合物。"},{"id":"otsu4-041","cat":"butsuka","q":"プロパン（C₃H₈）1molを完全燃焼させるのに必要な酸素は何molか。","choices":["2mol","4mol","5mol","3mol"],"answer":2,"exp":"C₃H₈＋5O₂→3CO₂＋4H₂O。酸素原子は右辺で3×2＋4×1＝10個なので O₂は5mol。"},{"id":"otsu4-042","cat":"butsuka","q":"一酸化炭素に関する記述として誤っているものは。","choices":["有機物の不完全燃焼で発生する","空気中で青い炎を出して燃える","毒性が強い","空気より重く、燃えない気体である"],"answer":3,"exp":"一酸化炭素は空気よりわずかに軽く、可燃性で有毒。燃えない・空気より重いのは二酸化炭素。"},{"id":"otsu4-043","cat":"butsuka","q":"水溶液のpHに関する記述として正しいものは。","choices":["pH7は中性で、7より小さいほど酸性が強い","pH7は酸性で、数値が大きいほど酸性が強い","pH14は中性である","pHが小さいほどアルカリ性が強い"],"answer":0,"exp":"pH7が中性。7未満は酸性、7を超えるとアルカリ性（塩基性）。"},{"id":"otsu4-044","cat":"butsuka","q":"自然発火に関する記述として正しいものは。","choices":["通風がよいほど熱が蓄積して自然発火しやすい","乾性油がしみこんだ布を積み重ねておくと、酸化熱が蓄積して自然発火することがある","ヨウ素価が小さい油ほど自然発火しやすい","不乾性油ほど自然発火しやすい"],"answer":1,"exp":"アマニ油などの乾性油（ヨウ素価が大きい）は空気中で酸化しやすく、熱がこもると自然発火する。"},{"id":"otsu4-045","cat":"seishitsu","q":"第4類危険物に共通する性質として誤っているものは。","choices":["蒸気は空気より軽く、高所に滞留しやすい","引火しやすい","電気の不良導体が多く、静電気が蓄積しやすい","液体の比重は1より小さいものが多い"],"answer":0,"exp":"第4類の蒸気は一般に空気より重く（蒸気比重1より大）、低所に滞留しやすい。"},{"id":"otsu4-046","cat":"seishitsu","q":"第4類危険物の火災予防の方法として誤っているものは。","choices":["容器は密栓して冷暗所に貯蔵する","容器は通気をよくするため、ふたを開けて保管する","発生した蒸気は屋外の高所に排出する","火気や高温体を近づけない"],"answer":1,"exp":"蒸気の発生・漏れを防ぐため容器は密栓する。"},{"id":"otsu4-047","cat":"seishitsu","q":"ガソリンなど非水溶性の第4類危険物の火災に、棒状の水による消火が適さない理由は。","choices":["水によって爆発的に分解するため","水が電気分解されて酸素が発生するため","危険物が水に浮いて燃え広がるおそれがあるため","水と反応して可燃性ガスを発生するため"],"answer":2,"exp":"多くは水より軽く水に溶けないため、水に浮いて火面が拡大する。泡・粉末・二酸化炭素・ハロゲン化物で窒息消火する。"},{"id":"otsu4-048","cat":"seishitsu","q":"アルコールやアセトンなど水溶性液体の火災に用いる泡消火剤として適切なものは。","choices":["強化液の棒状放射","棒状の水","水溶性液体用泡消火剤（耐アルコール泡）","一般の たん白泡消火剤"],"answer":2,"exp":"水溶性液体は一般の泡を溶かして消してしまうので、耐アルコール泡を使う。"},{"id":"otsu4-049","cat":"seishitsu","q":"自動車ガソリンの性状として誤っているものは。","choices":["燃焼範囲はおよそ1.4〜7.6vol%である","引火点は40℃以上である","蒸気は空気の3〜4倍程度の重さがある","オレンジ系色に着色されている"],"answer":1,"exp":"ガソリンの引火点は−40℃以下。引火点40℃以上は灯油。発火点は約300℃。"},{"id":"otsu4-050","cat":"seishitsu","q":"灯油の性状として正しいものは。","choices":["発火点はガソリンより低い","水によく溶ける","引火点は常温（20℃）より低い","液比重は1より大きい"],"answer":0,"exp":"灯油の発火点は約220℃でガソリン（約300℃）より低い。引火点は40℃以上、水に溶けず水より軽い。"},{"id":"otsu4-051","cat":"seishitsu","q":"軽油の性状として誤っているものは。","choices":["淡黄色または淡褐色の液体である","第1石油類に分類される","水に溶けない","引火点は45℃以上である"],"answer":1,"exp":"軽油は灯油と同じく第2石油類（引火点21℃以上70℃未満）。"},{"id":"otsu4-052","cat":"seishitsu","q":"重油の性状として誤っているものは。","choices":["燃え出すと液温が高くなり消火が困難になる","第3石油類に分類される","水より重く、水に沈む","粘り気のある褐色または暗褐色の液体である"],"answer":2,"exp":"重油の比重は0.9〜1.0程度で一般に水より軽い。"},{"id":"otsu4-053","cat":"seishitsu","q":"特殊引火物の定義として正しいものは。","choices":["1気圧で発火点100℃以下、または引火点−20℃以下かつ沸点40℃以下のもの","1気圧で引火点250℃未満の動植物の油","引火点21℃以上70℃未満のもの","引火点21℃未満のもの"],"answer":0,"exp":"ジエチルエーテル、二硫化炭素、アセトアルデヒド、酸化プロピレンなどが特殊引火物。"},{"id":"otsu4-054","cat":"seishitsu","q":"二硫化炭素の貯蔵方法として正しいものは。","choices":["容器のふたを開けて蒸気を逃がす","灯油の中に浸して貯蔵する","容器に水を張って蒸気の発生を抑える","直射日光の当たる場所で通風をよくして貯蔵する"],"answer":2,"exp":"二硫化炭素は水より重く（比重約1.3）水に溶けないため、水を張って貯蔵（水没貯蔵）できる。発火点は約90℃と非常に低い。"},{"id":"otsu4-055","cat":"seishitsu","q":"ジエチルエーテルの性状として誤っているものは。","choices":["日光や空気に触れると爆発性の過酸化物を生じることがある","引火点は−40℃以下と非常に低い","蒸気には麻酔性がある","燃焼範囲が狭く、引火の危険は小さい"],"answer":3,"exp":"ジエチルエーテルの燃焼範囲は約1.9〜36vol%と広く、非常に引火しやすい。"},{"id":"otsu4-056","cat":"seishitsu","q":"第4類の品名と物品の組合せとして誤っているものは。","choices":["第1石油類 ― アセトン","第1石油類 ― 灯油","第3石油類 ― グリセリン","第2石油類 ― 酢酸"],"answer":1,"exp":"灯油は第2石油類。第1石油類はガソリン、アセトン、ベンゼン、トルエンなど（引火点21℃未満）。"},{"id":"otsu4-057","cat":"seishitsu","q":"第3石油類の引火点の範囲として正しいものは（1気圧）。","choices":["21℃未満","21℃以上70℃未満","200℃以上250℃未満","70℃以上200℃未満"],"answer":3,"exp":"第1石油類21℃未満、第2石油類21℃以上70℃未満、第3石油類70℃以上200℃未満、第4石油類200℃以上250℃未満。"},{"id":"otsu4-058","cat":"seishitsu","q":"メタノールの性状として誤っているものは。","choices":["引火点は常温（20℃）より低い","水に溶ける","毒性はなく、飲用にも使われる","燃えるときの炎が淡く見えにくい"],"answer":2,"exp":"メタノールは毒性が強く、誤飲すると失明や死亡のおそれがある。引火点は約11℃。"},{"id":"otsu4-059","cat":"seishitsu","q":"エタノールの火災の消火方法として最も適切でないものは。","choices":["水溶性液体用泡消火剤を放射する","粉末消火剤を放射する","一般のたん白泡消火剤で覆う","二酸化炭素消火剤を放射する"],"answer":2,"exp":"エタノールは水溶性なので一般の泡は消泡されて効果が薄い。耐アルコール泡、二酸化炭素、粉末などが有効。"},{"id":"otsu4-060","cat":"seishitsu","q":"ベンゼンとトルエンに共通する性状として正しいものは。","choices":["水によく溶ける","引火点が100℃以上である","芳香族炭化水素で、水に溶けにくい","蒸気は空気より軽い"],"answer":2,"exp":"どちらも第1石油類の非水溶性。ベンゼンは毒性が強く、トルエンの毒性はベンゼンより低い。"},{"id":"otsu4-061","cat":"seishitsu","q":"酢酸の性状として誤っているものは。","choices":["腐食性がある","水によく溶ける","常温では固体で、加熱しないと液体にならない","純度の高いものは冬期などに凝固することがある"],"answer":2,"exp":"酢酸の融点は約17℃。常温では液体だが寒いと凝固する（氷酢酸）。第2石油類の水溶性。"},{"id":"otsu4-062","cat":"seishitsu","q":"動植物油類のうち、乾性油の特徴として正しいものは。","choices":["引火点は−20℃以下である","ヨウ素価が小さく、自然発火しにくい","ヨウ素価が大きく、自然発火しやすい","水によく溶ける"],"answer":2,"exp":"ヨウ素価130以上が乾性油（アマニ油、キリ油など）。不飽和度が高く酸化しやすいので自然発火に注意。"},{"id":"otsu4-063","cat":"seishitsu","q":"ガソリンを容器に詰め替えたり移送したりする際の静電気対策として誤っているものは。","choices":["流速をできるだけ速くして短時間で終える","作業場所の湿度を高く保つ","合成繊維の衣服を避け、帯電防止服を着用する","配管や容器を接地する"],"answer":0,"exp":"流速が速いほど静電気が発生しやすい。流速を遅くするのが対策。"},{"id":"otsu4-064","cat":"seishitsu","q":"第4類危険物の火災に適応しない消火器は。","choices":["二酸化炭素を放射する消火器","泡を放射する消火器","粉末（リン酸塩類等）を放射する消火器","棒状の水を放射する消火器"],"answer":3,"exp":"棒状の水は火面を広げるおそれがあり不適。強化液も霧状なら適応するが棒状は不適。"},{"id":"otsu4-065","cat":"hourei","q":"グリセリン（第3石油類・水溶性液体）の指定数量は。","choices":["2000L","6000L","1000L","4000L"],"answer":3,"exp":"第3石油類は非水溶性2000L・水溶性4000L。水溶性は非水溶性の2倍と覚える（第1・第2・第3石油類共通）。"},{"id":"otsu4-066","cat":"hourei","q":"酢酸（第2石油類・水溶性液体）の指定数量は。","choices":["4000L","2000L","400L","1000L"],"answer":1,"exp":"第2石油類は非水溶性（灯油・軽油など）1000L、水溶性（酢酸など）2000L。"},{"id":"otsu4-067","cat":"hourei","q":"指定数量の倍数にかかわらず、定期点検の対象とならない製造所等は。","choices":["地下タンクを有する給油取扱所","簡易タンク貯蔵所","移動タンク貯蔵所","地下タンク貯蔵所"],"answer":1,"exp":"屋内タンク貯蔵所・簡易タンク貯蔵所・販売取扱所は定期点検の義務がない。地下タンク貯蔵所と移動タンク貯蔵所はすべて対象。"},{"id":"otsu4-068","cat":"hourei","q":"屋外タンク貯蔵所が定期点検の対象となるのは、指定数量の倍数がいくつ以上のときか。","choices":["100以上","150以上","10以上","200以上"],"answer":3,"exp":"製造所・一般取扱所10以上、屋外貯蔵所100以上、屋内貯蔵所150以上、屋外タンク貯蔵所200以上（地下タンク貯蔵所・移動タンク貯蔵所はすべて）。"},{"id":"otsu4-069","cat":"hourei","q":"定期点検を行うことができる者として誤っているものは。","choices":["危険物取扱者の立会いを受けた者","危険物取扱者","危険物施設保安員","危険物取扱者の立会いのない、免状を持たない従業員"],"answer":3,"exp":"定期点検は危険物取扱者、危険物施設保安員、または危険物取扱者の立会いを受けた者が行う。"},{"id":"otsu4-070","cat":"hourei","q":"危険物の取扱作業に従事していなかった危険物取扱者（過去2年以内に免状交付・講習受講なし）が、新たに取扱作業に従事することになった。保安講習の受講期限は。","choices":["従事することとなった日から3か月以内","受講の義務はない","従事することとなった日から1年以内","従事することとなった日から3年以内"],"answer":2,"exp":"原則は従事開始から1年以内。ただし従事開始前2年以内に免状交付または受講していれば、その日以後の最初の4月1日から3年以内でよい。"},{"id":"otsu4-071","cat":"seishitsu","q":"灯油にガソリンを混ぜた場合の危険性として正しいものは。","choices":["引火点が下がり、常温でも引火しやすくなる","水に溶けやすくなる","発火点が上がって安全になる","引火点が上がり、引火しにくくなる"],"answer":0,"exp":"灯油（引火点40℃以上）に引火点−40℃以下のガソリンが混ざると、混合物の引火点が大きく下がり危険。灯油用容器に誤ってガソリンを入れないこと。"},{"id":"otsu4-072","cat":"seishitsu","q":"第4類危険物のうち、発火点が最も低いとされる物品は。","choices":["二硫化炭素","ガソリン","灯油","ジエチルエーテル"],"answer":0,"exp":"二硫化炭素の発火点は約90℃。ジエチルエーテル約160℃、灯油約220℃、ガソリン約300℃。"}]},"tsushin2":{"id":"tsushin2","name":"2級電気通信工事施工管理 第一次検定","short":"2級電通施工","description":"電気通信工学・電気通信設備・施工管理法・法規","categories":[{"id":"kogaku","name":"電気通信工学","refs":["電気通信工学の基礎（デシベル、2進数、論理回路、光ファイバ、変調）"]},{"id":"setsubi","name":"電気通信設備","refs":["IEEE 802.3/802.11 規格の概要、同軸ケーブル JIS 呼称、光ファイバ施工の一般知識"]},{"id":"kanren","name":"関連分野（電気・土木・建築）","refs":["土木・建築の基礎、電気設備の技術基準の解釈（接地）、建築基準法第33条"]},{"id":"sekou","name":"施工管理法","refs":["労働安全衛生規則（第518〜528条ほか）、酸素欠乏症等防止規則 第2条、クレーン等安全規則、品質管理の基礎"]},{"id":"hoki","name":"法規","refs":["建設業法・同施行令、労働基準法、道路法・道路交通法、有線電気通信法 第3条、電波法、廃棄物処理法、建設リサイクル法施行令（e-Gov）"]}],"exam":{"questions":40,"minutes":130,"distribution":{"kogaku":9,"setsubi":7,"kanren":4,"sekou":13,"hoki":7},"pass":{"type":"total","ratio":0.6,"label":"解答40問中24問以上正解（60%以上）"},"note":"本試験は65問出題・40問解答（電気通信工学12問中9問、電気通信設備20問中7問、関連分野7問中3問、設計・契約1問必須、法規12問中7問、施工管理法9問必須、能力問題4問必須）。試験時間2時間10分。合格基準は全国建設研修センターの令和8年度前期合格発表で「解答する40問（必須14問・選択26問）のうち24問以上正解（60%以上）」。本アプリは4択に統一し、この配分を目安に40問を出題します（設計・契約・能力問題は施工管理法に含めています）。","source":"https://www.jctc.jp/kentei/260707e_uwe09r/index.html , https://www.jctc.jp/kentei/info/datasheets20260707.pdf , https://www.jctc.jp/kentei/themes/tebiki_2e03_08.pdf","checked":"2026-11-05"},"version":"1.0.0","questions":[{"id":"tsushin2-001","cat":"kogaku","q":"電力比が100倍のとき、これをデシベルで表すと何dBか。","choices":["10dB","20dB","40dB","100dB"],"answer":1,"exp":"電力比のデシベルは 10log₁₀(P₂/P₁)＝10log₁₀100＝20dB。"},{"id":"tsushin2-002","cat":"kogaku","q":"電圧比が10倍のとき、これをデシベルで表すと何dBか（インピーダンスは等しいものとする）。","choices":["1dB","100dB","10dB","20dB"],"answer":3,"exp":"電圧比のデシベルは 20log₁₀(V₂/V₁)＝20log₁₀10＝20dB。電力は電圧の2乗に比例するため係数が20になる。"},{"id":"tsushin2-003","cat":"kogaku","q":"入力1mWの信号が、損失10dBのケーブルを通った後、利得30dBの増幅器で増幅された。出力電力は。","choices":["10mW","1000mW","100mW","20mW"],"answer":2,"exp":"総合利得は −10＋30＝＋20dB（＝100倍）。1mW×100＝100mW。dBは足し算・引き算で計算できる。"},{"id":"tsushin2-004","cat":"kogaku","q":"10mWを dBm で表すと。","choices":["100dBm","20dBm","10dBm","1dBm"],"answer":2,"exp":"dBmは1mWを基準(0dBm)とした値。10log₁₀(10mW/1mW)＝10dBm。"},{"id":"tsushin2-005","cat":"kogaku","q":"2進数の1011を10進数で表すと。","choices":["9","1011","11","13"],"answer":2,"exp":"1×8＋0×4＋1×2＋1×1＝11。"},{"id":"tsushin2-006","cat":"kogaku","q":"16進数のFFを10進数で表すと。","choices":["1515","256","15","255"],"answer":3,"exp":"F＝15。15×16＋15＝255。8ビットで表せる最大値。"},{"id":"tsushin2-007","cat":"kogaku","q":"2入力NAND回路の出力が「0」になる入力の組合せは。","choices":["A＝0、B＝0","A＝1、B＝0","A＝0、B＝1","A＝1、B＝1"],"answer":3,"exp":"NANDはANDの否定。両入力が1のときだけ出力0、それ以外は1。"},{"id":"tsushin2-008","cat":"kogaku","q":"光ファイバの構造に関する記述として正しいものは。","choices":["コアの屈折率はクラッドの屈折率より大きい","クラッドは光を通さない金属でできている","コアの屈折率はクラッドの屈折率より小さい","コアとクラッドの屈折率は等しい"],"answer":0,"exp":"コアの屈折率を高くすることで、境界で全反射させて光をコア内に閉じ込める。"},{"id":"tsushin2-009","cat":"kogaku","q":"シングルモード光ファイバの特徴として正しいものは。","choices":["コア径がマルチモードより大きい","モード分散が大きく長距離伝送に向かない","マルチモードに比べて伝送帯域が広く、長距離伝送に適する","LANの短距離配線専用である"],"answer":2,"exp":"シングルモードはコア径が約10μmと小さく伝搬モードが1つのためモード分散がなく、広帯域・長距離に向く。"},{"id":"tsushin2-010","cat":"kogaku","q":"光ファイバの損失のうち、波長の4乗に反比例するものは。","choices":["接続損失","吸収損失（OH基）","曲げ損失","レイリー散乱損失"],"answer":3,"exp":"レイリー散乱はガラスの微小な密度ゆらぎによる散乱で、波長が長いほど小さくなる（λ⁻⁴に比例）。"},{"id":"tsushin2-011","cat":"kogaku","q":"周波数3GHzの電磁波の波長は（電磁波の速度を3×10⁸m/sとする）。","choices":["1m","1cm","10m","10cm"],"answer":3,"exp":"波長λ＝c/f＝3×10⁸/3×10⁹＝0.1m＝10cm。"},{"id":"tsushin2-012","cat":"kogaku","q":"周波数帯の名称と範囲の組合せとして正しいものは。","choices":["VHF ― 3〜30MHz","HF ― 30〜300MHz","UHF ― 300MHz〜3GHz","SHF ― 300MHz〜3GHz"],"answer":2,"exp":"HF 3〜30MHz、VHF 30〜300MHz、UHF 300MHz〜3GHz、SHF 3〜30GHz。地上デジタル放送はUHF帯。"},{"id":"tsushin2-013","cat":"kogaku","q":"QAM（直交振幅変調）の説明として正しいものは。","choices":["搬送波の振幅だけを変化させる","搬送波の振幅と位相の両方を変化させて情報を伝える","パルスの幅を変化させる","搬送波の周波数だけを変化させる"],"answer":1,"exp":"QAMは振幅と位相を組み合わせ、1シンボルで多くのビットを送る。AMは振幅、FMは周波数、PSKは位相を変化させる。"},{"id":"tsushin2-014","cat":"kogaku","q":"最高周波数4kHzのアナログ音声信号をPCMで伝送する。標本化定理に基づく最低の標本化周波数は。","choices":["16kHz","8kHz","2kHz","4kHz"],"answer":1,"exp":"標本化周波数は信号の最高周波数の2倍以上必要。4kHz×2＝8kHz。"},{"id":"tsushin2-015","cat":"kogaku","q":"PCM（パルス符号変調）の処理の順序として正しいものは。","choices":["符号化 → 標本化 → 量子化","量子化 → 標本化 → 符号化","標本化 → 量子化 → 符号化","標本化 → 符号化 → 量子化"],"answer":2,"exp":"時間方向に区切る（標本化）→振幅を段階値に丸める（量子化）→2進符号にする（符号化）。"},{"id":"tsushin2-016","cat":"kogaku","q":"10μFのコンデンサ2個を直列に接続したときの合成静電容量は。","choices":["5μF","2.5μF","20μF","10μF"],"answer":0,"exp":"コンデンサの直列は抵抗の並列と同じ形の式。10×10/(10＋10)＝5μF。並列なら20μF。"},{"id":"tsushin2-017","cat":"kogaku","q":"正弦波交流電圧の最大値が141Vのとき、実効値はおよそ何Vか。","choices":["200V","70V","100V","141V"],"answer":2,"exp":"実効値＝最大値/√2＝141/1.414≒100V。"},{"id":"tsushin2-018","cat":"setsubi","q":"1000BASE-Tに関する記述として正しいものは。","choices":["最大伝送距離は500mである","カテゴリ3のケーブルで規定の性能が出る","UTPケーブルでの最大伝送距離は100mである","光ファイバを使用する規格である"],"answer":2,"exp":"1000BASE-Tはツイストペアケーブルの4対すべてを使い、最大伝送距離は100m。ケーブルはカテゴリ5以上（実務ではカテゴリ5e以上が一般的）。"},{"id":"tsushin2-019","cat":"setsubi","q":"10GBASE-Tで100mの伝送を行う場合に用いられるケーブルのカテゴリとして適切なものは。","choices":["カテゴリ5e","カテゴリ5","カテゴリ3","カテゴリ6A"],"answer":3,"exp":"10GBASE-Tを100mで使うにはカテゴリ6A以上が必要。"},{"id":"tsushin2-020","cat":"setsubi","q":"OSI参照モデルで、IPによる経路制御（ルーティング）を行う層は。","choices":["第2層（データリンク層）","第4層（トランスポート層）","第3層（ネットワーク層）","第1層（物理層）"],"answer":2,"exp":"ルータは第3層でIPアドレスにより転送。L2スイッチは第2層でMACアドレスにより転送。TCP/UDPは第4層。"},{"id":"tsushin2-021","cat":"setsubi","q":"IPv6アドレスのビット長は。","choices":["48ビット","64ビット","32ビット","128ビット"],"answer":3,"exp":"IPv4は32ビット、IPv6は128ビット。MACアドレスは48ビット。"},{"id":"tsushin2-022","cat":"setsubi","q":"サブネットマスクが255.255.255.0（/24）のネットワークで、ホストに割り当てられるIPアドレスの最大数は。","choices":["256","254","253","255"],"answer":1,"exp":"ホスト部8ビットで256通り。ネットワークアドレス（全0）とブロードキャストアドレス（全1）を除いて254。"},{"id":"tsushin2-023","cat":"setsubi","q":"TCPとUDPに関する記述として正しいものは。","choices":["TCPはコネクション型で、再送制御などにより信頼性を確保する","TCPはリアルタイム性を優先し再送を行わない","TCPとUDPはOSI参照モデルの第3層のプロトコルである","UDPはコネクション型で、到達確認を行う"],"answer":0,"exp":"TCPは信頼性重視、UDPはコネクションレスで軽量・リアルタイム向き。どちらも第4層。"},{"id":"tsushin2-024","cat":"setsubi","q":"ネットワークに接続した端末にIPアドレスなどを自動的に割り当てるプロトコルは。","choices":["DNS","DHCP","NTP","SMTP"],"answer":1,"exp":"DHCPはIPアドレス等の自動割当て。DNSはドメイン名とIPアドレスの対応付け、SMTPはメール送信、NTPは時刻同期。"},{"id":"tsushin2-025","cat":"setsubi","q":"PoE（Power over Ethernet）の説明として正しいものは。","choices":["光ファイバで電力を送る技術","無線LANの暗号化方式","電力線を使ってデータ通信を行う技術","LANケーブルを通して機器に電力を供給する技術"],"answer":3,"exp":"PoEはネットワークカメラや無線LANアクセスポイントなどに、LANケーブル1本でデータと電力を送る。電力線通信はPLC。"},{"id":"tsushin2-026","cat":"setsubi","q":"2.4GHz帯の無線LANに関する記述として正しいものは。","choices":["電子レンジなどと同じ周波数帯のため干渉を受けることがある","5GHz帯より障害物に弱い","免許が必要な周波数帯である","IEEE802.11acは2.4GHz帯のみを使用する"],"answer":0,"exp":"2.4GHz帯はISMバンドで電子レンジやBluetoothと干渉しやすい。一般に5GHz帯より回り込みに強い。802.11acは5GHz帯。"},{"id":"tsushin2-027","cat":"setsubi","q":"光ファイバ心線の接続方法のうち、一般に接続損失が最も小さいものは。","choices":["どれも同じ","コネクタ接続","メカニカルスプライス","融着接続"],"answer":3,"exp":"融着接続はファイバ同士を放電で溶かしてつなぐため損失が小さい。コネクタ接続は着脱できるが損失が大きめ。"},{"id":"tsushin2-028","cat":"setsubi","q":"OTDR（光パルス試験器）で測定できるものとして正しいものは。","choices":["光ファイバのコア径","後方散乱光を利用した光ファイバの損失分布や破断点の位置","伝送装置のビット誤り率","ケーブルの絶縁抵抗"],"answer":1,"exp":"OTDRは光パルスを入射し、戻ってくる後方散乱光・反射光から距離ごとの損失や障害点の位置を測る。"},{"id":"tsushin2-029","cat":"setsubi","q":"テレビ共同受信設備で、幹線から一部の信号を取り出し、残りを幹線に送り続ける機器は。","choices":["分岐器","分配器","混合器","ブースタ"],"answer":0,"exp":"分岐器は幹線の信号の一部を取り出す（挿入損失小・結合損失大）。分配器は入力を均等に分ける。混合器は複数の信号を1本にまとめる。"},{"id":"tsushin2-030","cat":"setsubi","q":"同軸ケーブル「5C-FB」の「C」が表すものは。","choices":["銅の外部導体であること","屋外専用であること","特性インピーダンスが75Ωであること","特性インピーダンスが50Ωであること"],"answer":2,"exp":"数字は外部導体のおおよその内径（mm）、Cは75Ω（Dなら50Ω）、Fは発泡ポリエチレン絶縁、Bはアルミ箔テープ＋編組。"},{"id":"tsushin2-031","cat":"setsubi","q":"BS・110度CS放送を受信するパラボラアンテナに関する記述として正しいものは。","choices":["受信には12GHz帯を使い、コンバータ（LNB）へ電源供給が必要である","コンバータへの電源供給は不要である","アンテナの向きは北向きにする","UHF帯を使うので八木アンテナで受信する"],"answer":0,"exp":"衛星放送は12GHz帯。LNBで1GHz帯程度に周波数変換するため、テレビやブースタからDC電源を供給する。日本では南西方向に向ける。"},{"id":"tsushin2-032","cat":"setsubi","q":"ツイストペアケーブルで2本の導線をより合わせる主な目的は。","choices":["外部からの電磁誘導による雑音の影響を低減する","ケーブルの引張強度を上げる","ケーブルを細くする","直流抵抗を小さくする"],"answer":0,"exp":"より合わせることで誘導される雑音が打ち消し合い、またクロストークも減る。"},{"id":"tsushin2-033","cat":"setsubi","q":"通信機器を雷サージから保護するために、電源線や通信線に設置する機器は。","choices":["SPD（サージ防護デバイス）","UPS（無停電電源装置）","PBX（構内交換機）","ONU（光回線終端装置）"],"answer":0,"exp":"SPDは雷などの過電圧を接地へ逃がして機器を守る。UPSは停電時に電力を供給する装置。"},{"id":"tsushin2-034","cat":"setsubi","q":"ネットワークの境界に設置し、通信を許可・遮断して不正アクセスを防ぐ仕組みは。","choices":["メディアコンバータ","スプリッタ","ファイアウォール","リピータハブ"],"answer":2,"exp":"ファイアウォールは送信元・宛先・ポートなどのルールで通信を制御する。"},{"id":"tsushin2-035","cat":"setsubi","q":"無線LANのセキュリティ方式として、最も新しく安全性が高いとされるものは。","choices":["WPA","MACアドレスフィルタリングのみ","WPA3","WEP"],"answer":2,"exp":"WEPは脆弱で使用すべきでない。現在はWPA2・WPA3が使われ、WPA3が最新。"},{"id":"tsushin2-036","cat":"kanren","q":"地山の土量1000m³を掘削したとき、ほぐした状態の土量は（ほぐし率L＝1.2）。","choices":["1000m³","1200m³","1440m³","833m³"],"answer":1,"exp":"ほぐした土量＝地山土量×L＝1000×1.2＝1200m³。運搬計画ではこのほぐした量で考える。"},{"id":"tsushin2-037","cat":"kanren","q":"バックホウの用途として最も適しているものは。","choices":["機械が設置された地盤より低い場所の掘削","盛土の締固め","機械より高い場所の掘削","アスファルト舗装の敷きならし"],"answer":0,"exp":"バックホウ（ドラグショベル）はバケットを手前に引く動作で、地盤より低い位置の掘削に適する。締固めはローラ。"},{"id":"tsushin2-038","cat":"kanren","q":"コンクリートに関する記述として正しいものは。","choices":["水セメント比が大きいほど強度は大きくなる","打込み後は急激に乾燥させるとよい","水セメント比が小さいほど、一般に強度は大きくなる","コンクリートは引張りに強く圧縮に弱い"],"answer":2,"exp":"水が多いほど硬化後の空隙が増えて強度が下がる。コンクリートは圧縮に強く引張りに弱いので鉄筋で補う。打込み後は湿潤養生する。"},{"id":"tsushin2-039","cat":"kanren","q":"鉄筋コンクリート造で、鉄筋のかぶり厚さを確保する主な目的として誤っているものは。","choices":["コンクリートの使用量を減らすため","鉄筋の腐食を防ぐ（耐久性）","火災時に鉄筋を熱から守る（耐火性）","鉄筋とコンクリートの付着を確保する"],"answer":0,"exp":"かぶり厚さは耐久性・耐火性・付着力の確保のため。"},{"id":"tsushin2-040","cat":"kanren","q":"水準測量で主に使用される機器は。","choices":["レベル","トランシット（セオドライト）","クリノメータ","平板"],"answer":0,"exp":"レベルと標尺で高低差を測るのが水準測量。トランシットは角度を測る。"},{"id":"tsushin2-041","cat":"kanren","q":"接地工事の種類と接地抵抗値の組合せとして正しいものは（原則）。","choices":["D種接地工事 ― 10Ω以下","C種接地工事 ― 100Ω以下","A種接地工事 ― 100Ω以下","A種接地工事 ― 10Ω以下"],"answer":3,"exp":"A種10Ω以下、C種10Ω以下、D種100Ω以下（C・Dは0.5秒以内の自動遮断で500Ω以下）。B種は計算で決まる。"},{"id":"tsushin2-042","cat":"kanren","q":"建築基準法上、避雷設備を設けなければならない建築物は、原則として高さ何mを超えるものか。","choices":["10m","20m","31m","60m"],"answer":1,"exp":"高さ20mを超える建築物には原則として有効に避雷設備を設ける。"},{"id":"tsushin2-043","cat":"kanren","q":"架空配電線路の電柱に支線を設ける主な目的は。","choices":["電線のたるみを大きくする","電線の張力などによる電柱の傾きや倒壊を防ぐ","電柱の高さを高くする","雷を大地に逃がす"],"answer":1,"exp":"支線は電線の不平均張力に対抗して電柱を支える。"},{"id":"tsushin2-044","cat":"sekou","q":"次のネットワーク工程で、所要日数（クリティカルパスの日数）は。〔作業A(3日):①→②、作業B(4日):①→③、作業C(5日):②→④、作業D(3日):③→④、作業E(2日):④→⑤〕","choices":["17日","10日","9日","12日"],"answer":1,"exp":"経路は A→C→E＝3＋5＋2＝10日、B→D→E＝4＋3＋2＝9日。最も長い経路がクリティカルパスで10日。"},{"id":"tsushin2-045","cat":"sekou","q":"クリティカルパスに関する記述として誤っているものは。","choices":["クリティカルパスは1本とは限らない","開始から終了までの最も長い経路である","クリティカルパス上の作業が遅れると全体工期が遅れる","クリティカルパス上の作業には余裕日数（トータルフロート）が多い"],"answer":3,"exp":"クリティカルパス上の作業のトータルフロートは0。重点管理が必要。"},{"id":"tsushin2-046","cat":"sekou","q":"バーチャート工程表の特徴として正しいものは。","choices":["作業間の関連やクリティカルパスが明確に分かる","各作業の達成率だけを示し、所要日数は分からない","作成が容易で各作業の開始・終了時期が分かりやすいが、作業間の関連は分かりにくい","工事全体の出来高の推移を曲線で表したものである"],"answer":2,"exp":"作業間の関連が明確なのはネットワーク工程表。達成率を示すのはガントチャート。出来高累計曲線はSカーブ。"},{"id":"tsushin2-047","cat":"sekou","q":"品質管理に用いるQC七つ道具と用途の組合せとして誤っているものは。","choices":["パレート図 ― 2つの特性の相関を見る","特性要因図 ― 結果と原因の関係を整理する","管理図 ― 工程が安定しているかを見る","ヒストグラム ― データのばらつきの分布を見る"],"answer":0,"exp":"2つの特性の相関を見るのは散布図。パレート図は不良項目などを大きい順に並べ、重点項目を見つける図。"},{"id":"tsushin2-048","cat":"sekou","q":"PDCAサイクルの順序として正しいものは。","choices":["計画 → 確認 → 実施 → 処置","実施 → 計画 → 処置 → 確認","確認 → 計画 → 実施 → 処置","計画 → 実施 → 確認 → 処置"],"answer":3,"exp":"Plan（計画）→Do（実施）→Check（確認・評価）→Act（処置・改善）を繰り返して品質を高める。"},{"id":"tsushin2-049","cat":"sekou","q":"抜取検査を適用するのが適切な場合は。","choices":["ロットが非常に小さく全数検査が容易な場合","検査が破壊試験となる場合","不良品が1つでも混入すると重大な事故につながる場合","人命に関わる安全装置の動作確認"],"answer":1,"exp":"破壊検査は全数検査ができないので抜取検査を使う。不良の見逃しが許されない場合は全数検査。"},{"id":"tsushin2-050","cat":"sekou","q":"わく組足場以外の足場の作業床で、墜落の危険がある箇所に設ける手すり等の高さは何cm以上か（労働安全衛生規則）。","choices":["75cm","85cm","60cm","110cm"],"answer":1,"exp":"わく組足場以外の足場では、高さ85cm以上の手すり等と、高さ35〜50cmの中さん等を設ける。足場の作業床の幅は原則40cm以上。"},{"id":"tsushin2-051","cat":"sekou","q":"高さ2m以上の箇所で作業床を設けることが困難なときの措置として正しいものは。","choices":["作業員を2人以上にすればよい","防網を張り、労働者に墜落制止用器具を使用させる","ヘルメットを着用させれば作業床は不要","作業時間を短くすればよい"],"answer":1,"exp":"作業床の設置が困難な場合は防網を張り、墜落制止用器具を使用させるなど墜落防止措置を講じる。"},{"id":"tsushin2-052","cat":"sekou","q":"脚立の使用に関する記述として正しいものは。","choices":["開き止めは作業しにくいので外して使う","脚と水平面との角度は85度以上にする","天板の上に立って作業するのが最も安全である","脚と水平面との角度を75度以下とし、開き止めの金具を確実に掛ける"],"answer":3,"exp":"労働安全衛生規則で脚立は脚と水平面との角度75度以下、開き止めを備えることなどが定められている。"},{"id":"tsushin2-053","cat":"sekou","q":"酸素欠乏の定義として正しいものは（酸素欠乏症等防止規則）。","choices":["空気中の酸素濃度が10%未満である状態","空気中の酸素濃度が21%未満である状態","空気中の酸素濃度が18%未満である状態","二酸化炭素濃度が1%以上である状態"],"answer":2,"exp":"酸素濃度18%未満が酸素欠乏。マンホールや地下ピットに入る前には酸素濃度を測定し、換気を行う。"},{"id":"tsushin2-054","cat":"sekou","q":"作業開始前に、その日の作業内容や危険のポイントを作業員同士で短時間話し合う活動は。","choices":["ツールボックスミーティング（TBM）","パレート分析","完成検査","工程会議（月例）"],"answer":0,"exp":"TBMは作業前ミーティング。危険予知（KY）活動と組み合わせて行うことが多い。"},{"id":"tsushin2-055","cat":"sekou","q":"つり上げ荷重3tの移動式クレーンの運転に必要な資格は。","choices":["小型移動式クレーン運転技能講習の修了（またはそれ以上の免許）","玉掛け技能講習の修了のみ","特別教育の修了のみ","資格は不要"],"answer":0,"exp":"移動式クレーンは、1t未満が特別教育、1t以上5t未満が小型移動式クレーン運転技能講習、5t以上が免許。"},{"id":"tsushin2-056","cat":"sekou","q":"作業床の高さが10m以上の高所作業車の運転（道路上の走行を除く）に必要な資格は。","choices":["高所作業車運転技能講習の修了","普通自動車運転免許のみ","特別教育の修了","資格は不要"],"answer":0,"exp":"作業床の高さ10m以上は技能講習、10m未満は特別教育。"},{"id":"tsushin2-057","cat":"sekou","q":"施工計画を立てる際の事前調査として、一般に行わないものは。","choices":["既設設備や埋設物の調査","現場周辺の道路・交通状況の調査","近隣住民・関係機関との調整事項の確認","竣工後の利用者満足度調査"],"answer":3,"exp":"施工計画の事前調査は、契約条件の確認と現場条件（地形、交通、埋設物、近隣、電力・用水など）の調査。"},{"id":"tsushin2-058","cat":"sekou","q":"光ファイバケーブルを管路に敷設するときの注意点として誤っているものは。","choices":["通線前に管路内の清掃や導通確認を行う","ケーブルにねじれが生じないようにする","許容張力を超えないよう張力を管理する","作業性を優先し、許容曲げ半径より小さく曲げて引き入れる"],"answer":3,"exp":"許容曲げ半径より小さく曲げると損失増加や断線の原因になる。"},{"id":"tsushin2-059","cat":"sekou","q":"管理図で工程が安定状態にないと判断できる例として正しいものは。","choices":["点が管理限界線の外に出た","データ数が多い","点が中心線の上下にランダムに分布している","点がすべて管理限界線の内側にあり、くせがない"],"answer":0,"exp":"管理限界線外の点や、中心線の片側に点が連続する（連）などのくせがあれば異常と判断する。"},{"id":"tsushin2-060","cat":"hoki","q":"建設業法で、建設業の許可を受けなくても請け負うことができる「軽微な建設工事」（建築一式工事以外）の工事1件の請負代金の額は。","choices":["1500万円未満","1000万円未満","100万円未満","500万円未満"],"answer":3,"exp":"建築一式工事以外は1件500万円未満が軽微な建設工事。建築一式工事は1500万円未満または延べ面積150m²未満の木造住宅。"},{"id":"tsushin2-061","cat":"hoki","q":"2以上の都道府県の区域内に営業所を設けて建設業を営もうとする者が受ける許可は。","choices":["総務大臣の許可","国土交通大臣の許可","市町村長の許可","都道府県知事の許可"],"answer":1,"exp":"1つの都道府県のみに営業所があれば知事許可、2以上なら国土交通大臣許可。許可の有効期間は5年。"},{"id":"tsushin2-062","cat":"hoki","q":"建設業の許可の有効期間は。","choices":["1年","3年","5年","10年"],"answer":2,"exp":"許可は5年ごとに更新を受けなければ効力を失う。"},{"id":"tsushin2-063","cat":"hoki","q":"建設業法上、主任技術者に関する記述として正しいものは。","choices":["下請負人は主任技術者を置かなくてよい","請負代金が500万円以上の工事にだけ置けばよい","主任技術者は施工計画の作成に関わってはならない","許可を受けた建設業者は、元請・下請にかかわらず工事現場に主任技術者を置く"],"answer":3,"exp":"主任技術者は施工計画の作成、工程管理、品質管理、技術上の指導監督などを行う。元請・下請を問わず必要。"},{"id":"tsushin2-064","cat":"hoki","q":"労働基準法で定める法定労働時間（原則）は。","choices":["1日7時間・1週35時間","1日10時間・1週40時間","1日8時間・1週48時間","1日8時間・1週40時間"],"answer":3,"exp":"法定労働時間は1日8時間・1週40時間。超えて働かせるには36協定の締結・届出が必要。"},{"id":"tsushin2-065","cat":"hoki","q":"労働基準法で、使用者が労働者を解雇しようとする場合の予告期間は（原則）。","choices":["少なくとも30日前","少なくとも14日前","少なくとも60日前","少なくとも7日前"],"answer":0,"exp":"少なくとも30日前に予告するか、30日分以上の平均賃金（解雇予告手当）を支払う。"},{"id":"tsushin2-066","cat":"hoki","q":"労働基準法で、満18歳未満の者（年少者）について正しいものは。","choices":["危険有害業務にも制限なく就かせられる","原則として深夜業（午後10時〜午前5時）に就かせてはならない","年少者の雇用には都道府県知事の許可が必要","時間外労働は月45時間まで可能"],"answer":1,"exp":"年少者は原則として深夜業や危険有害業務に就かせられず、時間外・休日労働も原則禁止。"},{"id":"tsushin2-067","cat":"hoki","q":"道路上で工事を行うために道路に工作物を設けて継続して使用する（道路占用）場合に、許可を受ける相手は。","choices":["都道府県公安委員会","道路管理者","国土交通大臣のみ","所轄警察署長"],"answer":1,"exp":"道路占用は道路法により道路管理者の許可。道路上で工事作業を行う（道路使用）は道路交通法により所轄警察署長の許可。"},{"id":"tsushin2-068","cat":"hoki","q":"道路交通法で、道路において工事や作業をしようとする者が許可を受ける相手は。","choices":["所轄警察署長","消防署長","市町村長","道路管理者"],"answer":0,"exp":"道路使用許可は所轄警察署長。道路占用許可（道路管理者）とセットで必要になることが多い。"},{"id":"tsushin2-069","cat":"hoki","q":"有線電気通信法で、有線電気通信設備を設置しようとする者の届出として正しいものは（届出が必要な場合）。","choices":["工事開始の日の2週間前までに総務大臣に届け出る","工事開始前に都道府県知事の許可を受ける","工事完了後30日以内に経済産業大臣に届け出る","届出は一切不要である"],"answer":0,"exp":"有線電気通信設備の設置は、設置の工事の開始の日の2週間前まで（工事を要しないときは設置の日から2週間以内）に総務大臣へ届け出る（一定の設備は除く）。"},{"id":"tsushin2-070","cat":"hoki","q":"電波法で、無線局を開設しようとする者が原則として受けなければならないものは。","choices":["都道府県知事の登録","経済産業大臣の許可","総務大臣の免許","市町村長への届出"],"answer":2,"exp":"無線局の開設は原則として総務大臣の免許が必要（免許不要局を除く）。"},{"id":"tsushin2-071","cat":"hoki","q":"建設工事に伴って生じた産業廃棄物の処理責任を負う排出事業者は、原則として誰か。","choices":["発注者","元請業者","下請業者","廃棄物の運搬業者"],"answer":1,"exp":"建設工事の廃棄物は元請業者が排出事業者として処理責任を負う。マニフェスト（産業廃棄物管理票）の写しは5年間保存。"},{"id":"tsushin2-072","cat":"hoki","q":"建設リサイクル法の特定建設資材に該当しないものは。","choices":["木材","アスファルト・コンクリート","プラスチック","コンクリート"],"answer":2,"exp":"特定建設資材はコンクリート、コンクリート及び鉄から成る建設資材、木材、アスファルト・コンクリートの4品目。"},{"id":"tsushin2-073","cat":"hoki","q":"労働安全衛生法で、掘削面の高さが2m以上となる地山の掘削作業について選任が必要なものは。","choices":["職長のみ","地山の掘削作業主任者","安全衛生推進者","衛生管理者"],"answer":1,"exp":"掘削面の高さ2m以上の地山の掘削作業では、技能講習を修了した者のうちから地山の掘削作業主任者を選任する。"},{"id":"tsushin2-074","cat":"sekou","q":"移動はしごを使用する際の留意点として、厚生労働省のリーフレットで示されているものは。","choices":["滑り止めは天候が悪いときだけ使用する","立て掛け角度はできるだけ寝かせて45度程度にする","はしごの上端を上端床から60cm以上突出させ、立て掛け角度は75度程度とする","はしごの幅は20cm程度あればよい"],"answer":2,"exp":"移動はしごは幅30cm以上、滑り止め等の転位防止措置が必要（安衛則第527条）。上端の60cm以上の突出と75度程度の角度が推奨されている。"},{"id":"tsushin2-075","cat":"sekou","q":"酸素欠乏症等防止規則で「酸素欠乏等」とされる状態のうち、硫化水素の濃度の基準は。","choices":["100万分の1（1ppm）を超える状態","1000分の1（0.1%）を超える状態","100万分の10（10ppm）を超える状態","100分の1（1%）を超える状態"],"answer":2,"exp":"酸素欠乏は酸素濃度18%未満、酸素欠乏等はそれに加えて硫化水素濃度が100万分の10を超える状態をいう。"},{"id":"tsushin2-076","cat":"hoki","q":"有線電気通信設備を設置した者が、届け出た設備の概要などを変更しようとするときの届出期限は（工事を要する場合）。","choices":["変更の工事の完了後30日以内","届出は不要","変更の工事の開始の日の1か月前まで","変更の工事の開始の日の2週間前まで"],"answer":3,"exp":"有線電気通信法第3条第3項。工事を要しないときは変更の日から2週間以内に総務大臣へ届け出る。"},{"id":"tsushin2-077","cat":"hoki","q":"建設業法で、特定建設業の許可が必要となるのは、発注者から直接請け負った1件の工事（建築一式工事以外）について、下請代金の総額がいくら以上となる下請契約を締結して施工する場合か（2025年2月施行の改正後）。","choices":["5000万円以上","500万円以上","8000万円以上","4500万円以上"],"answer":0,"exp":"建設業法施行令第2条。2025年2月1日から4500万円→5000万円に引き上げ（建築工事業は7000万円→8000万円）。"},{"id":"tsushin2-078","cat":"hoki","q":"建設工事で生じた産業廃棄物を委託処理する際に交付するマニフェスト（産業廃棄物管理票）の写しの保存期間は。","choices":["1年間","5年間","3年間","10年間"],"answer":1,"exp":"排出事業者・収集運搬業者・処分業者とも、マニフェストの写しを5年間保存する。"}]}}};
